import { toggleNotifications } from "./actions";
import { cookies } from "next/headers";

export default async function Home() {
  const cookieStore = await cookies();
  const notificationsEnabled = cookieStore.get("notifications")?.value === "on";

  return (
    <main>
      <form action={toggleNotifications}>
        <p>Notifications: {notificationsEnabled ? "On" : "Off"}</p>
        <button type="submit">
          {notificationsEnabled ? "Turn off notifications" : "Turn on notifications"}
        </button>
      </form>
    </main>
  );
}

